import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_columns = [
        "DATE",
        "TIME",
        "Qty",
        "PRODUCTID",
        "Price",
        "ProductType",
        "ProductDescription",
        "URL",
        "Comments",
    ]
    expected_normalized = [
        re.sub(r"[^a-z0-9]+", "", value.lower())
        for value in expected_columns
    ]
    width = len(expected_columns)

    def normalize(value):
        return re.sub(
            r"[^a-z0-9]+",
            "",
            value.lstrip("\ufeff").strip().lower(),
        )

    def is_header(record):
        if len(record) < width:
            return False
        return [normalize(value) for value in record[:width]] == expected_normalized

    try:
        csv.field_size_limit(100000000)
    except (OverflowError, csv.Error):
        pass

    start_offset = None
    offset = 0
    for physical_line in raw_csv.splitlines(keepends=True):
        try:
            parsed = next(csv.reader(io.StringIO(physical_line, newline="")))
        except (csv.Error, StopIteration):
            parsed = []
        if is_header(parsed):
            start_offset = offset
            break
        offset += len(physical_line)

    source = raw_csv[start_offset:] if start_offset is not None else raw_csv

    try:
        records = list(csv.reader(io.StringIO(source, newline="")))
    except csv.Error:
        records = []
        for line in source.splitlines():
            try:
                records.extend(csv.reader(io.StringIO(line, newline="")))
            except csv.Error:
                records.append(line.split(","))

    header_found = False
    columns = list(expected_columns)
    rows = []

    url_pattern = re.compile(r"^[A-Za-z][A-Za-z0-9+.-]*://")

    def repair_width(record):
        record = list(record)

        if len(record) == width:
            return record

        url_index = None
        for index, value in enumerate(record):
            if url_pattern.match(value.strip()):
                url_index = index
                break

        if len(record) < width:
            if url_index is not None and 5 <= url_index < 7:
                record[url_index:url_index] = [""] * (7 - url_index)
            if len(record) < width:
                record.extend([""] * (width - len(record)))
            elif len(record) > width:
                record = record[:width - 1] + [
                    ",".join(record[width - 1:])
                ]
            return record

        if url_index is not None and url_index >= 7:
            middle = record[5:url_index]
            split_at = 1
            for index in range(1, len(middle)):
                candidate = middle[index].strip()
                if len(candidate) >= 50:
                    split_at = index
                    break

            product_type = ",".join(middle[:split_at])
            description = ",".join(middle[split_at:])
            comments = ",".join(record[url_index + 1:])
            repaired = (
                record[:5]
                + [product_type, description, record[url_index], comments]
            )
            if len(repaired) == width:
                return repaired

        return record[:width - 1] + [",".join(record[width - 1:])]

    for record in records:
        if not header_found:
            if is_header(record):
                columns = [
                    value.lstrip("\ufeff").strip()
                    for value in record[:width]
                ]
                header_found = True
            continue

        if is_header(record):
            continue

        if not record or (len(record) == 1 and record[0] == ""):
            continue

        rows.append(repair_width(record))

    if not header_found:
        rows = []
        for record in records:
            if not record or (len(record) == 1 and record[0] == ""):
                continue
            if is_header(record):
                continue
            rows.append(repair_width(record))

    return {"columns": columns, "rows": rows}
